<div class="grid gap-4 md:grid-cols-2"><label>Destination name<input class="{{ $input }}" name="name" value="{{ $destination?->name }}" required></label><label>Telegram chat ID<input class="{{ $input }}" name="chat_id" value="{{ $destination?->chat_id }}" required></label><label>Chat type<select class="{{ $input }}" name="type">@foreach(['private','group','channel'] as $value)<option value="{{ $value }}" @selected($destination?->type===$value)>{{ ucfirst($value) }}</option>@endforeach</select></label><label>Detail level<select class="{{ $input }}" name="detail_level"><option value="summary" @selected($destination?->detail_level!=='personal')>Limited detail (no personal contacts)</option><option value="personal" @selected($destination?->detail_level==='personal')>Personal detail (trusted destination)</option></select></label><label class="md:col-span-2">Allowed Telegram user IDs for commands (comma separated)<input class="{{ $input }}" name="allowed_user_ids" value="{{ implode(',',$destination?->allowed_user_ids??[]) }}"><span class="text-xs text-slate-500">Empty means commands are denied. Commands require this chat ID and one of these user IDs.</span></label></div><label class="inline-flex items-center gap-2"><input type="hidden" name="enabled" value="0"><input type="checkbox" name="enabled" value="1" @checked($destination?->enabled??true)> Destination enabled</label>